import type { Note } from "./note.ts";
import { slugify } from "./slug.ts";

/**
 * Plain Markdown export, built only from saved records (never regenerated by a model), so it's deterministic and
 * readable in any editor or Obsidian. The frontmatter keeps the stable id so a future import can skip duplicates.
 */
export const EXPORT_FORMAT_VERSION = 1;
export const UNSORTED_FOLDER = "Unsorted";

/** YAML double-quoted scalars use JSON-compatible escaping, so JSON.stringify is a safe way to quote. */
const yaml = (value: string) => JSON.stringify(value);

export function noteTitle(note: Pick<Note, "title" | "raw_text">): string {
  if (note.title) return note.title;
  const firstLine = note.raw_text.trim().split("\n")[0] ?? "";
  return firstLine.length > 60 ? `${firstLine.slice(0, 57).trimEnd()}…` : firstLine || "Untitled";
}

export function noteToMarkdown(note: Note): string {
  const title = noteTitle(note);
  const frontmatter = [
    "---",
    `id: ${yaml(note.id)}`,
    `title: ${yaml(title)}`,
    `created: ${yaml(note.created_at)}`,
    `updated: ${yaml(note.updated_at)}`,
    `category: ${note.category ? yaml(note.category) : "null"}`,
    note.tags.length ? `tags:\n${note.tags.map((tag) => `  - ${yaml(tag)}`).join("\n")}` : "tags: []",
    `status: ${yaml(note.status)}`,
    // A date ("2026-10-23") or a date and time ("2026-10-23 14:00"), in the note's own timezone.
    ...(note.due_date ? [`due: ${yaml(note.due_time ? `${note.due_date} ${note.due_time}` : note.due_date)}`] : []),
    ...(note.uncertain.length ? [`uncertain:\n${note.uncertain.map((p) => `  - ${yaml(p)}`).join("\n")}`] : []),
    ...(note.user_edited ? ["edited: true"] : []),
    "source: \"mimu\"",
    "---",
  ].join("\n");

  const transcript = note.raw_text
    .trim()
    .split("\n")
    .map((line) => `> ${line}`)
    .join("\n");

  const body =
    note.status === "processed" && note.markdown
      ? `${note.markdown.trim()}\n\n## Original transcript\n\n${transcript}`
      : // Not organized yet: the raw capture is the note.
        note.raw_text.trim();

  return `${frontmatter}\n\n# ${title}\n\n${body}\n`;
}

/** Folder names keep the category's readable casing ("Project-Ideas"), minus anything a filesystem might reject. */
export function folderName(category: string | null): string {
  if (!category) return UNSORTED_FOLDER;
  const cleaned = category
    .normalize("NFKC")
    .replace(/[^\p{L}\p{N} _-]/gu, "")
    .trim()
    .replace(/\s+/g, "-");
  return cleaned || UNSORTED_FOLDER;
}

export function noteFilename(note: Pick<Note, "id" | "title" | "raw_text">): string {
  return `${slugify(noteTitle(note)) || slugify(note.id) || "note"}.md`;
}

export interface ExportEntry {
  path: string;
  note: Note;
}

/** Assign every note a unique path like "Project-Ideas/duplicate-file-analyzer.md", adding -2, -3… on collisions. */
export function planExport(notes: readonly Note[]): ExportEntry[] {
  const used = new Set<string>();
  const ordered = [...notes].sort((a, b) => a.created_at.localeCompare(b.created_at) || a.id.localeCompare(b.id));
  return ordered.map((note) => {
    const folder = note.status === "processed" ? folderName(note.category) : UNSORTED_FOLDER;
    const base = noteFilename(note).replace(/\.md$/, "");
    let path = `${folder}/${base}.md`;
    for (let n = 2; used.has(path.toLowerCase()); n++) path = `${folder}/${base}-${n}.md`;
    used.add(path.toLowerCase());
    return { path, note };
  });
}

export function exportManifest(entries: readonly ExportEntry[], exportedAt: string) {
  return {
    format: "mimu-export",
    version: EXPORT_FORMAT_VERSION,
    exported_at: exportedAt,
    count: entries.length,
    notes: entries.map(({ path, note }) => ({
      id: note.id,
      path,
      title: noteTitle(note),
      category: note.category,
      status: note.status,
      created_at: note.created_at,
    })),
  };
}
